defs: [
  ["Market research", "The process of gathering, analysing and interpreting information about a market."],
  ["Product-orientated business", "A business whose main focus of activity is the product itself — it produces first and then looks for a market."],
  ["Market-orientated business", "A business that carries out market research to find out consumer wants before a product is developed and produced."],
  ["Marketing budget", "A financial plan for the marketing of a product or product range for a specified period of time."],
  ["Primary research (field research)", "The collection of original data through direct contact with potential or existing customers."],
  ["Secondary research (desk research)", "The use of information that has already been collected and is available for use by others."],
  ["Questionnaire", "A set of questions to be answered as a means of collecting data for market research."],
  ["Focus group", "A group of people, representative of the target market, who discuss a product or campaign with a researcher present."],
  ["Sample", "The group of people selected to respond to a market research exercise."],
  ["Random sample", "A sample in which every member of the population has the same chance of being selected."],
  ["Quota sample", "A sample in which people are selected on the basis of certain characteristics such as age, gender or income."],
  ["Quantitative data", "Information about quantities — how many, how much, what percentage."],
  ["Qualitative data", "Information involving opinions or judgements — what customers like, dislike and why."]
],
